// Superadmin console: audit trail, activity feed, service health and the Superadmin's own appearance.
// Master DB only. Tenant identity is never taken from the client here; Superadmin identity comes from the signed session.
import { performance } from 'node:perf_hooks';
import { realtimeStatus } from './realtime.js';

export const consoleDDL = [
  "CREATE TABLE IF NOT EXISTS master_audit_events (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,company_id BIGINT NULL REFERENCES companies(id) ON DELETE SET NULL,company_name VARCHAR(160) NOT NULL DEFAULT '',action VARCHAR(40) NOT NULL,detail VARCHAR(300) NOT NULL DEFAULT '',actor_id BIGINT NULL,actor_name VARCHAR(120) NOT NULL DEFAULT '',created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP)",
  // One row per Superadmin. Separate from companies, so it never affects a tenant or the Admin change allowance.
  'CREATE TABLE IF NOT EXISTS master_user_preferences (master_user_id BIGINT PRIMARY KEY REFERENCES master_users(id) ON DELETE CASCADE,template_id BIGINT NULL REFERENCES ui_templates(id) ON DELETE SET NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP)',
  'CREATE INDEX IF NOT EXISTS master_audit_company ON master_audit_events (company_id,id)',
  'CREATE INDEX IF NOT EXISTS master_audit_time ON master_audit_events (created_at)',
];

const positive = (value) => { const n = Number(value); return Number.isSafeInteger(n) && n > 0 ? n : null; };

export function consoleHandlers({ pool }) {
  /** Best effort: an audit failure must never undo or block the action it records. */
  async function audit(req, action, company, detail = '') {
    try {
      const actorId = positive(req.masterSession?.id);
      const [[actor]] = actorId ? await pool.query('SELECT name FROM master_users WHERE id=?', [actorId]) : [[null]];
      await pool.query('INSERT INTO master_audit_events (company_id,company_name,action,detail,actor_id,actor_name) VALUES (?,?,?,?,?,?)',
        [positive(company?.id), String(company?.companyName || '').slice(0, 160), action, String(detail).slice(0, 300), actorId, actor?.name || 'Superadmin']);
    } catch (error) { console.error('Audit write failed:', error.message); }
  }

  /** Recorded events plus existing template and registration history, newest first. */
  async function activity(req, res) {
    const companyId = req.query.companyId === undefined ? null : positive(req.query.companyId);
    if (req.query.companyId !== undefined && !companyId) return res.status(400).json({ message: 'Choose a valid company' });
    const limit = Math.min(200, positive(req.query.limit) || 60), where = companyId ? 'WHERE "companyId"=?' : '', args = companyId ? [companyId] : [];
    const [rows] = await pool.query(`SELECT * FROM (
        SELECT 'audit-'||e.id key,e.company_id "companyId",e.company_name "companyName",e.action,e.detail,e.actor_name actor,e.created_at "createdAt" FROM master_audit_events e
        UNION ALL SELECT 'tpl-'||a.id,a.company_id,a.company_name,'template.'||a.source,COALESCE(p.name,'—')||' → '||t.name,a.assigned_by_name,a.created_at FROM template_assignments a JOIN ui_templates t ON t.id=a.template_id LEFT JOIN ui_templates p ON p.id=a.previous_template_id
        UNION ALL SELECT 'treq-'||q.id,q.company_id,q.company_name,'template.requested','Asked for '||t.name,q.requested_by_name,q.created_at FROM template_change_requests q JOIN ui_templates t ON t.id=q.requested_template_id
        UNION ALL SELECT 'trev-'||q.id,q.company_id,q.company_name,'template.'||q.status,t.name||CASE WHEN q.review_note<>'' THEN ' · '||q.review_note ELSE '' END,q.reviewed_by_name,q.reviewed_at FROM template_change_requests q JOIN ui_templates t ON t.id=q.requested_template_id WHERE q.reviewed_at IS NOT NULL
        UNION ALL SELECT 'reset-'||r.id,r.company_id,r.company_name,'template.allowance-reset',r.previous_count||' changes were used',r.reset_by_name,r.created_at FROM template_allowance_resets r
        UNION ALL SELECT 'reg-'||g.id,g.company_id,g.company_name,'registration.submitted',g.package_code||' · '||g.period_months||' months',g.admin_name,g.created_at FROM company_registration_requests g
      ) x ${where} ORDER BY "createdAt" DESC,key DESC LIMIT ${limit}`, args);
    res.json({ events: rows });
  }

  /** Only measured values; anything this process cannot observe is omitted, not estimated. */
  async function health(_req, res) {
    const started = performance.now();
    let database = { ok: true };
    try { await pool.query('SELECT 1'); } catch (error) { database = { ok: false, message: error.message }; }
    database.latencyMs = Math.round((performance.now() - started) * 10) / 10;
    const [[outbox]] = await pool.query("SELECT COUNT(*) FILTER (WHERE status='queued') queued,COUNT(*) FILTER (WHERE status='failed' AND created_at>NOW()-INTERVAL '24 hours') failed FROM notification_outbox").catch(() => [[null]]);
    const memory = process.memoryUsage();
    res.json({ checkedAt: new Date().toISOString(), database, realtime: realtimeStatus(), uptimeSeconds: Math.round(process.uptime()), memoryMb: Math.round(memory.rss / 1048576), heapMb: Math.round(memory.heapUsed / 1048576), node: process.version, notifications: outbox ? { queued: Number(outbox.queued), failedLastDay: Number(outbox.failed) } : null });
  }

  const preference = async (masterUserId) => {
    const [[row]] = await pool.query('SELECT t.id,t.code,t.version FROM master_user_preferences m JOIN ui_templates t ON t.id=m.template_id AND t.active WHERE m.master_user_id=?', [masterUserId]);
    return row || null;
  };
  async function getAppearance(req, res) {
    const [templates] = await pool.query('SELECT id,code,name,version,preview FROM ui_templates WHERE active ORDER BY id');
    res.json({ templates, current: await preference(req.masterSession.id) });
  }
  /** Unlimited, and scoped to the signed-in Superadmin only. */
  async function setAppearance(req, res) {
    const templateId = req.body?.templateId === null ? null : positive(req.body?.templateId);
    if (templateId === null && req.body?.templateId !== null) return res.status(400).json({ message: 'Choose a valid template' });
    const [[user]] = await pool.query('SELECT id FROM master_users WHERE id=? AND active=TRUE', [req.masterSession.id]);
    if (!user) return res.status(403).json({ message: 'An active Superadmin account is required' });
    if (templateId) {
      const [[template]] = await pool.query('SELECT id FROM ui_templates WHERE id=? AND active', [templateId]);
      if (!template) return res.status(404).json({ message: 'Template not found or inactive' });
    }
    await pool.query('INSERT INTO master_user_preferences (master_user_id,template_id,updated_at) VALUES (?,?,NOW()) ON CONFLICT (master_user_id) DO UPDATE SET template_id=EXCLUDED.template_id,updated_at=NOW() RETURNING master_user_id', [user.id, templateId]);
    res.json({ ok: true, current: await preference(user.id) });
  }
  return { audit, activity, health, getAppearance, setAppearance, preference };
}
